  'bdp.handLabel':'Hand total (1 → next backdash)', 'bdp.handTarget':n=>'target '+n+'f or less · 3f minimum',
  'bdp.dbLabel':'1 (d/b) hold', 'bdp.dbTarget':n=>'target '+n+'f or less · 1f minimum', 'bdp.tapLabel':'4 N 4', 'bdp.tapTarget':n=>'target '+n+'f or less · 2f minimum',
  'bdp.distLabel':'This backdash', 'bdp.distTarget':d=>'full backdash '+d+' m',
  'bdp.speedLabel':'Set speed', 'bdp.speedTarget':v=>'very fast from '+v+' m/s', 'bdp.speedTargetFor':v=>'best for this hand '+v+' m/s',
  'bdp.formula':(d,h,hand,v)=>'speed = distance × 60 ÷ (cancel − 1 + hand) = '+d+' m × 60 ÷ ('+h+'f − 1 + '+hand+'f) = '+v+' m/s',
  'bdp.sets':'Sets', 'bdp.avgSpeed':'Avg speed', 'bdp.bestSpeed':'Best speed', 'bdp.avgCut':'Avg cancel (f)', 'bdp.avgHand':'Avg hand (f)', 'bdp.bestChain':'Best chain',
  'bdp.note':(full,a,b,top,c)=>'A set runs from one backdash coming out to the next. Speed = that backdash\'s distance × 60 ÷ (cancel frame − 1 + hand frames; the backdash coming out is 1f). The distance curve is measured from the Tekken 8 practice-mode distance (a community sheet cross-checked with video data, average of the five Mishima-style characters); a full backdash is '+full+' m. A faster hand moves the best cancel slightly earlier, and with a 3–14f hand it stays within '+a+'–'+b+'f. Very fast ('+top+' m/s or more) is a '+c+'f hand cancelling at the best frame. Each character\'s curve differs a little.',
