  'tj.r.cancel':f=>'Cancel on '+f+'f', 'tj.r.early':f=>'Cancel on '+f+'f · before the knee', 'tj.r.late':f=>f+'f input ignored', 'tj.r.none':'Taunt left uncancelled', 'tj.r.split':'The taunt did not come out',
